namespace LandPortal.Infrastructure;
public static class VideoDiskBudget
{
    // Count generated bytes too, including crash orphans. Bound inventory; exhaustion closes new work.
    public static long StoredBytes(StorageOptions storage)
    {
        long total=0;var entries=0;
        foreach(var prefix in new[]{"video-original","video-output","video-subtitle"})
        {
            var root=Path.GetDirectoryName(MediaService.ResolveMediaPath(storage,prefix+"/boundary"))!;if(!Directory.Exists(root))continue;
            var pending=new Stack<string>();pending.Push(root);
            while(pending.TryPop(out var directory))foreach(var path in Directory.EnumerateFileSystemEntries(directory))
            {
                if(++entries>10000)throw new MediaUploadException("Kho video cần đối soát dung lượng trước khi nhận thêm tệp.",507);
                var key=Path.GetRelativePath(storage.MediaRoot,path).Replace('\\','/');MediaService.ResolveMediaPath(storage,key);var attr=File.GetAttributes(path);if((attr&FileAttributes.ReparsePoint)!=0)throw new MediaUploadException("Kho video có đường dẫn cần kiểm tra.",507);
                if((attr&FileAttributes.Directory)!=0)pending.Push(path);else total=checked(total+new FileInfo(path).Length);
            }
        }
        return total;
    }
}
